{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Hydroxocobalamin, a close corrinoid analogue sharing the same macrocyclic framework and nucleotide-loop phosphate, showed negligible oral bioavailability in human volunteers, directly supporting a low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "ATP, a highly polar phosphorylated molecule, achieved only 14.9 ± 2.5% estimated oral bioavailability even with proximal-release pellets in healthy volunteers, supporting that large ionized phosphate-containing molecules are poorly absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Levovirin, a polar nucleoside with very low Caco-2 permeability, had approximately 10% oral bioavailability in humans, supporting the expectation that the query's extreme polarity and permeability barriers lead to F < 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted low oral bioavailability (<20%): the query is a very large, fully ionized corrinoid with a phosphate-nucleotide loop; the closest analogue hydroxocobalamin has negligible oral bioavailability in humans, and other polar phosphorylated/nucleoside analogues also fall below 20%.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement exists for the exact query molecule.",
    "The closest analogue (hydroxocobalamin) has only moderate Morgan similarity (0.596), so exact quantitative transfer is uncertain.",
    "Potential corrinoid-specific active uptake mechanisms (e.g., intrinsic factor) are not quantified for this derivative."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C06"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "corrinoid oral bioavailability"
    }
  ],
  "revision_action": "initial"
}

